<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ChevronRight, Clock3, Compass, EyeOff, MapPinned, Radio, RefreshCw, Route, Sparkles, Star, Users } from '@lucide/vue'
import type { ActivityEvent, Friend, FriendNetwork, World } from './api'
import { buildReunionCards, buildTonightCards, type CompassMode, type InsightCard } from './insights'

const props=defineProps<{friends:Friend[];worlds:World[];events:ActivityEvent[];network:FriendNetwork|null;favoriteIds:string[];storageKey:string;realtimeLabel:string;routeLabel:string;loading:boolean}>()
const emit=defineEmits<{openFriend:[userId:string];openWorld:[worldId:string,location:string];loadNetwork:[];refresh:[]}>()
const mode=ref<CompassMode>('friends')
const timeBudget=ref<30|60|120>(60)
const ignored=ref<string[]>([])
const keep=ref<string[]>([])
const modes:{id:CompassMode;label:string;hint:string}[]=[
  {id:'friends',label:'跟朋友汇合',hint:'好友人数与可加入性优先'},
  {id:'reunion',label:'找久未见的人',hint:'兼顾当前在线与最近相遇'},
  {id:'explore',label:'探索新去处',hint:'收藏、历史与公开热度优先'},
]
const tonight=computed(()=>buildTonightCards(props.friends,props.worlds,props.favoriteIds,props.events,mode.value).slice(0,timeBudget.value===30?3:6))
const primary=computed(()=>tonight.value[0])
const alternatives=computed(()=>tonight.value.slice(1))
const reunion=computed(()=>buildReunionCards(props.friends,props.events).filter((item)=>item.targetUserId&&!ignored.value.includes(item.targetUserId)).sort((a,b)=>Number(keep.value.includes(b.targetUserId||''))-Number(keep.value.includes(a.targetUserId||''))||b.score-a.score))
const coverage=computed(()=>new Set(props.events.map((item)=>item.observedAt.slice(0,10)).filter(Boolean)).size)
const onlineCount=computed(()=>props.friends.filter(item=>item.online).length)
const joinableFriends=computed(()=>props.friends.filter(item=>item.online&&item.location?.startsWith('wrld_')&&!item.location.includes('~private(')))
const liveClusters=computed(()=>{
  const grouped=new Map<string,Friend[]>()
  for(const friend of joinableFriends.value){const items=grouped.get(friend.location!)||[];items.push(friend);grouped.set(friend.location!,items)}
  const worldByID=new Map(props.worlds.map(world=>[world.id,world]))
  return [...grouped.entries()].map(([location,people])=>({location,people,world:worldByID.get(location.split(':')[0])})).sort((a,b)=>b.people.length-a.people.length)
})
const knownWorldCount=computed(()=>new Set([...props.worlds.map(item=>item.id),...props.events.map(item=>item.worldId).filter(Boolean)]).size)
const modeCopy=computed(()=>modes.find(item=>item.id===mode.value)!)
const planSteps=computed(()=>{
  const steps:{label:string;card:InsightCard;note:string}[]=[]
  if(primary.value)steps.push({label:'首选',card:primary.value,note:primary.value.location?'当前可直接查看实例':'先查看公开实例是否可加入'})
  if(alternatives.value[0])steps.push({label:'候补',card:alternatives.value[0],note:'首选不可用时切换，不必重新筛选'})
  if(reunion.value[0])steps.push({label:'顺路联系',card:reunion.value[0],note:'在线且较久未见，可先打开好友档案确认状态'})
  return steps
})
function routeType(card:InsightCard){return card.location?'实时好友实例':card.reasons.some(item=>item.includes('收藏'))?'收藏/历史候选':card.reasons.some(item=>item.includes('本机记录'))?'历史候选':'公开热门候选'}
function actionLabel(card:InsightCard){return card.targetUserId?'查看好友':card.location?'查看实例':'查看世界'}
function preferenceKey(){return `vrc-harbor-reunion:${props.storageKey}`}
function persist(){localStorage.setItem(preferenceKey(),JSON.stringify({ignored:ignored.value,keep:keep.value,mode:mode.value,timeBudget:timeBudget.value}))}
function dismiss(userId?:string){if(!userId)return;ignored.value=[...new Set([...ignored.value,userId])];keep.value=keep.value.filter((id)=>id!==userId);persist()}
function toggleKeep(userId?:string){if(!userId)return;keep.value=keep.value.includes(userId)?keep.value.filter((id)=>id!==userId):[...keep.value,userId];persist()}
function selectMode(value:CompassMode){mode.value=value;persist()}
function selectBudget(value:30|60|120){timeBudget.value=value;persist()}
function open(card:InsightCard){if(card.targetUserId)emit('openFriend',card.targetUserId);else if(card.targetWorldId)emit('openWorld',card.targetWorldId,card.location||'')}
function shortTime(value:string){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
function openCluster(item:{location:string;world?:World}){emit('openWorld',item.location.split(':')[0],item.location)}
onMounted(()=>{try{const value=JSON.parse(localStorage.getItem(preferenceKey())||'{}');ignored.value=value.ignored??[];keep.value=value.keep??[];if(['friends','reunion','explore'].includes(value.mode))mode.value=value.mode;if([30,60,120].includes(value.timeBudget))timeBudget.value=value.timeBudget}catch{ignored.value=[];keep.value=[]}})
</script>

<template>
  <section class="compass-view wide-view">
    <div class="compass-hero panel"><div><span class="panel-kicker">今晚行动台</span><h2>别只推荐，直接给出下一步</h2><p>把实时好友位置、可加入性、久未见的人、收藏与历史世界合成一份可执行计划。</p></div><div class="compass-hero-actions"><div class="compass-state"><span><Radio :size="13"/>{{ realtimeLabel }}</span><span>{{ routeLabel }}</span><span>{{ coverage }} 天证据</span></div><button :disabled="loading" @click="emit('refresh')"><RefreshCw :class="{spin:loading}" :size="15"/>{{ loading?'刷新中':'刷新全部信号' }}</button></div></div>

    <div class="decision-bar panel"><div class="mode-switch"><button v-for="item in modes" :key="item.id" :class="{active:mode===item.id}" @click="selectMode(item.id)"><strong>{{ item.label }}</strong><small>{{ item.hint }}</small></button></div><div class="budget-switch"><span>今晚可用时间</span><button v-for="value in ([30,60,120] as const)" :key="value" :class="{active:timeBudget===value}" @click="selectBudget(value)">{{ value }} 分钟</button></div></div>

    <div class="compass-coverage panel"><div><b>{{ onlineCount }}</b><span>在线好友</span></div><div><b>{{ joinableFriends.length }}</b><span>可加入好友</span></div><div><b>{{ liveClusters.length }}</b><span>好友实例</span></div><div><b>{{ knownWorldCount }}</b><span>已知世界</span></div><div><b>{{ reunion.length }}</b><span>重逢候选</span></div></div>

    <section v-if="primary" class="recommendation-board">
      <article class="primary-route panel" :data-live="Boolean(primary.location)"><header><span><Sparkles :size="14"/>{{ modeCopy.label }} · 首选</span><b>{{ primary.score }} 分</b></header><div class="primary-copy"><span class="route-signal">{{ routeType(primary) }}</span><h3>{{ primary.title }}</h3><p>{{ primary.summary }}</p></div><ul><li v-for="reason in primary.reasons" :key="reason">{{ reason }}</li></ul><footer><small><Clock3 :size="12"/>建议有效至 {{ shortTime(primary.expiresAt) }}</small><button @click="open(primary)">{{ actionLabel(primary) }} <ChevronRight :size="14"/></button></footer></article>
      <article class="alternatives panel"><header><div><Route :size="16"/><strong>自动候补</strong></div><small>{{ alternatives.length }} 条</small></header><button v-for="(card,index) in alternatives" :key="card.id" @click="open(card)"><b>{{ index+2 }}</b><span><strong>{{ card.title }}</strong><small>{{ routeType(card) }} · {{ card.summary }}</small></span><em>{{ card.score }} 分</em><ChevronRight :size="14"/></button><p v-if="!alternatives.length">当前只有一个有证据支持的选项，不用低质量建议凑数。</p></article>
    </section>
    <article v-else class="route-empty panel"><Compass :size="27"/><strong>还没有可执行路线</strong><span>刷新后会重新读取在线好友、世界、收藏和本机历史；不会用缓存位置冒充实时位置。</span><button @click="emit('refresh')"><RefreshCw :size="14"/>立即刷新</button></article>

    <section v-if="planSteps.length" class="plan-timeline panel"><header><div><MapPinned :size="17"/><span><strong>{{ timeBudget }} 分钟行动草案</strong><small>按当前信号自动生成，点任意一步即可执行或核对</small></span></div><em>策略：{{ modeCopy.label }}</em></header><div><button v-for="(step,index) in planSteps" :key="`${step.label}-${step.card.id}`" @click="open(step.card)"><span class="step-index">{{ index+1 }}</span><span><b>{{ step.label }} · {{ step.card.title }}</b><small>{{ step.note }}</small></span><ChevronRight :size="15"/></button></div></section>

    <div class="compass-columns">
      <article class="cluster-panel panel"><header><div><Users :size="17"/><strong>实时好友实例雷达</strong></div><small>{{ liveClusters.length }} 个可加入位置</small></header><div class="cluster-list"><button v-for="cluster in liveClusters" :key="cluster.location" @click="openCluster(cluster)"><span class="cluster-count">{{ cluster.people.length }}</span><span><strong>{{ cluster.world?.name || '好友所在世界' }}</strong><small>{{ cluster.people.slice(0,4).map(item=>item.displayName).join('、') }}<template v-if="cluster.people.length>4"> 等 {{ cluster.people.length }} 人</template></small></span><em>立即核对</em><ChevronRight :size="14"/></button><p v-if="!liveClusters.length">目前没有好友公开可加入的位置。私人房、位置隐藏和离线好友不会被冒充成可加入路线。</p></div><footer><Radio :size="13"/>这里只显示当前好友状态中明确公开的世界实例。</footer></article>
      <article class="reunion-panel panel"><header><div><Sparkles :size="17"/><strong>重逢机会</strong></div><small>{{ reunion.length }} 位候选</small></header><div class="reunion-list"><div v-for="card in reunion.slice(0,8)" :key="card.id"><button class="reunion-main" @click="open(card)"><span :class="{kept:keep.includes(card.targetUserId||'')}"><Star :size="14"/></span><div><strong>{{ card.title }}</strong><small>{{ card.summary }}</small><em>{{ card.reasons[1] }}</em></div><ChevronRight :size="14"/></button><div class="reunion-actions"><button @click="toggleKeep(card.targetUserId)"><Star :size="12"/>{{ keep.includes(card.targetUserId||'')?'取消关注':'保持联系' }}</button><button @click="dismiss(card.targetUserId)"><EyeOff :size="12"/>暂不提醒</button></div></div><p v-if="!reunion.length">当前没有满足“至少 7 天未记录且现在在线”的好友；数据不足时不会制造候选。</p></div><footer><Users :size="13"/>偏好仅保存在本机，不上传也不推断私人位置。</footer></article>
    </div>
  </section>
</template>

<style scoped>
