.compass-coverage>div{display:flex;align-items:baseline;justify-content:center;gap:6px;min-height:40px;border-right:1px solid var(--line)}.compass-coverage>div:last-child{border:0}.compass-coverage b{color:var(--accent);font-size:20px}.compass-coverage span{color:var(--muted);font-size:11px}.recommendation-board{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(330px,.65fr);gap:12px}.primary-route{padding:18px}.primary-route[data-live=true]{border-color:color-mix(in srgb,var(--accent) 42%,var(--line));box-shadow:inset 0 4px 0 var(--accent)}.primary-route>header,.primary-route>header span,.primary-route>footer{display:flex;align-items:center}.primary-route>header{justify-content:space-between}.primary-route>header span{gap:6px;color:var(--accent);font-size:11px;font-weight:700}.primary-route>header b{color:var(--accent);font-size:13px}.primary-copy{margin-top:14px}.route-signal{display:inline-flex;padding:4px 7px;border-radius:5px;background:var(--accent-soft);color:var(--accent);font-size:10px;font-weight:700}.primary-copy h3{margin:8px 0 5px;font-size:23px}.primary-copy p{margin:0;color:var(--ink-soft);font-size:13px;line-height:1.55}.primary-route ul{display:grid;gap:5px;margin:15px 0;padding-left:18px;color:var(--muted);font-size:11px;line-height:1.55}.primary-route>footer{justify-content:space-between;padding-top:12px;border-top:1px solid var(--line)}.primary-route>footer small,.primary-route>footer button{display:flex;align-items:center;gap:5px}.primary-route>footer small{color:var(--muted);font-size:10px}.primary-route>footer button{height:34px;padding:0 11px;border:0;border-radius:7px;background:var(--accent);color:#fff;font-size:11px;cursor:pointer}.alternatives{padding:14px}.alternatives>header,.cluster-panel>header,.reunion-panel>header{display:flex;align-items:center;justify-content:space-between}.alternatives>header>div,.cluster-panel>header>div,.reunion-panel>header>div{display:flex;align-items:center;gap:7px}.alternatives header strong,.cluster-panel header strong,.reunion-panel header strong{font-size:13px}.alternatives header small,.cluster-panel header small,.reunion-panel header small{color:var(--muted);font-size:10px}.alternatives>button,.cluster-list>button{width:100%;display:grid;grid-template-columns:24px minmax(0,1fr) auto 16px;align-items:center;gap:7px;padding:10px 3px;border:0;border-top:1px solid var(--line);background:transparent;color:var(--ink);text-align:left;cursor:pointer}.alternatives>button:first-of-type,.cluster-list>button:first-child{margin-top:8px}.alternatives>button>b{width:22px;height:22px;display:grid;place-items:center;border-radius:50%;background:var(--surface-muted);color:var(--muted);font-size:10px}.alternatives>button span,.cluster-list>button span{min-width:0}.alternatives>button strong,.alternatives>button small,.cluster-list strong,.cluster-list small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.alternatives>button strong,.cluster-list strong{font-size:11px}.alternatives>button small,.cluster-list small{margin-top:3px;color:var(--muted);font-size:9px}.alternatives>button em,.cluster-list>button em{color:var(--accent);font-size:9px;font-style:normal;white-space:nowrap}.alternatives>p,.cluster-list>p{margin:30px 15px;color:var(--muted);font-size:10px;line-height:1.6;text-align:center}.plan-timeline{padding:14px}.plan-timeline>header{display:flex;align-items:center;justify-content:space-between}.plan-timeline>header>div{display:flex;align-items:center;gap:8px}.plan-timeline>header span strong,.plan-timeline>header span small{display:block}.plan-timeline>header span strong{font-size:13px}.plan-timeline>header span small{margin-top:2px;color:var(--muted);font-size:10px}.plan-timeline>header em{color:var(--accent);font-size:10px;font-style:normal}.plan-timeline>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin-top:11px}.plan-timeline button{display:grid;grid-template-columns:28px minmax(0,1fr) 16px;align-items:center;gap:8px;padding:10px;border:1px solid var(--line);border-radius:8px;background:var(--surface-muted);color:var(--ink);text-align:left;cursor:pointer}.step-index{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:var(--accent-soft);color:var(--accent);font-size:11px;font-weight:800}.plan-timeline button span:nth-child(2){min-width:0}.plan-timeline button b,.plan-timeline button small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.plan-timeline button b{font-size:11px}.plan-timeline button small{margin-top:3px;color:var(--muted);font-size:9px}.compass-columns{display:grid;grid-template-columns:1.15fr .85fr;gap:12px}.cluster-panel,.reunion-panel{padding:14px}.cluster-list{margin-top:8px}.cluster-list>button{grid-template-columns:34px minmax(0,1fr) auto 16px}.cluster-count{width:32px;height:32px;display:grid!important;place-items:center;border-radius:9px;background:var(--accent-soft);color:var(--accent);font-size:13px;font-weight:800}.cluster-panel>footer,.reunion-panel>footer{display:flex;align-items:center;gap:5px;margin-top:8px;padding-top:9px;border-top:1px solid var(--line);color:var(--muted);font-size:9px}.reunion-list{margin-top:10px}.reunion-list>div{border-top:1px solid var(--line)}.reunion-list>div:first-child{border-top:0}.reunion-main{width:100%;display:grid;grid-template-columns:28px 1fr 16px;align-items:center;gap:7px;padding:9px 2px;border:0;background:transparent;color:var(--ink);text-align:left;cursor:pointer}.reunion-main>span{width:26px;height:26px;display:grid;place-items:center;border-radius:50%;background:var(--surface-muted);color:var(--muted)}.reunion-main>span.kept{color:var(--warning);background:var(--warning-soft)}.reunion-main div{min-width:0}.reunion-main strong,.reunion-main small,.reunion-main em{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reunion-main strong{font-size:11px}.reunion-main small{margin-top:2px;color:var(--ink-soft);font-size:9px}.reunion-main em{margin-top:2px;color:var(--muted);font-size:8px;font-style:normal}.reunion-actions{display:flex;justify-content:flex-end;gap:4px;padding:0 2px 7px}.reunion-actions button{display:flex;align-items:center;gap:3px;padding:4px 6px;border:0;border-radius:5px;background:var(--surface-muted);color:var(--muted);font-size:8px;cursor:pointer}.reunion-list>p{margin:40px 20px;color:var(--muted);text-align:center;font-size:10px;line-height:1.6}.route-empty{min-height:190px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted)}.route-empty strong{margin:8px 0 4px;color:var(--ink)}.route-empty span{max-width:620px;font-size:11px;line-height:1.6;text-align:center}.route-empty>button{margin-top:12px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}
@container (max-width:1050px){.decision-bar{align-items:stretch;flex-direction:column}.recommendation-board,.compass-columns{grid-template-columns:1fr}.plan-timeline>div{grid-template-columns:1fr}.compass-hero{align-items:flex-start;gap:12px;flex-direction:column}.compass-hero-actions{width:100%;justify-content:space-between}.compass-coverage{grid-template-columns:repeat(3,minmax(0,1fr))}}
@container (max-width:680px){.mode-switch{grid-template-columns:1fr}.budget-switch{align-items:stretch;flex-wrap:wrap}.budget-switch>span{width:100%}.compass-state{flex-wrap:wrap}.compass-hero-actions{align-items:stretch;flex-direction:column}.compass-hero-actions>button{justify-content:center}.compass-coverage{grid-template-columns:repeat(2,minmax(0,1fr))}.primary-copy h3{font-size:19px}}
</style>
